// Graphic posters, pattern tiles and icon sets measured on reference pictures.
// Organic outlines are traced from the reference and fitted with Béziers
// (crates/morpho-core/examples/refpath.rs); anything generative — squiggles,
// sunbursts, stripes, dots — is rebuilt with the tool that makes it, so it
// stays editable.
import type { Dash, Squiggle } from '../engine/types';
import { background, fill, group, mods, stroke, symbolLayer, type Background, type Node, type Project, type ShapeLayer, type Style, style } from './model';
import type { Template } from './templates';
import { frame } from './templatesStudio';
import { PATTERN_KINDS as PATTERN_NAMES } from '../render/effects';

const project = (name: string, layers: Node[], bg: Background, canvas: { width: number; height: number }): Project => ({ version: 2, name, canvas, layers, background: bg, fonts: [] });
const solid = (c: string) => background(fill('solid', c));
const ink = (c: string): Style => style('flat', { fill: c });

/** Give a pen line a squiggle and/or dashes; lengths in reference px (× k). */
function along(l: ShapeLayer, k: number, sq: Partial<Squiggle> | null, dash: Partial<Dash> | null = null): ShapeLayer {
  if (l.content.type !== 'line') return l;
  if (sq) l.content.squiggle = { kind: 'zigzag', amplitude: 20, spacing: 24, smooth: 0, loops: 1.2, perSegment: true, flatEnds: false, flip: false, ...sq, ...(sq.amplitude !== undefined && { amplitude: sq.amplitude * k }), ...(sq.spacing !== undefined && { spacing: sq.spacing * k }) };
  if (dash) l.content.dash = { dash: (dash.dash ?? 16) * k, gap: (dash.gap ?? 12) * k, offset: (dash.offset ?? 0) * k };
  return l;
}

/** A disc from its reference centre and radius. */
const disc = (P: (x: number, y: number) => { x: number; y: number }, k: number, x: number, y: number, r: number, st: Style, name = 'Dot') => symbolLayer('circle', 2 * r * k, { ...P(x, y), name, style: st });

/** A pattern-material style; `kind` indexes PATTERN_KINDS. */
const pat = (kind: number, ink: string, paper: string, p: Record<string, number | string> = {}): Style => style('pattern', { kind, ink, paper, paperAlpha: 1, scale: 40, weight: 0.35, angle: 0, rays: 24, amount: 0.35, stagger: 0, cx: 0, cy: 0, phaseX: 0, phaseY: 0, seed: 3, ...p });

