      const grad = (fill1: string, fill2: string, angle: number, gradStart: number, gradEnd: number): Style => style('flat', { fill: fill1, fill2, gradient: 1, angle: angle ?? 180, gradStart: gradStart ?? 0, gradEnd: gradEnd ?? 1 });
