// ---- traced outlines (reference px) ----

/** A flat colour or a linear gradient: from, to, angle, start, end (fitted by least squares). */
type Paint = [string, string?, number?, number?, number?];
/** An icon vectorised from the reference: its tile's paint, then named regions bottom to top. */
interface VectorIcon {
  tile: Paint;
  regions: [string, string, ...Paint][];
}
